def get_seed_products():
    products = []
    for i, (cat, name, price, img_key, tag, desc) in enumerate(_RAW, start=1):
        products.append({
            "id": f"p{i}",
            "name": name,
            "category": cat,
            "price": price,
            "img": IMG[img_key],
            "tag": tag,
            "desc": desc,
            "rating": 4.7,
            "reviews": 40 + (i * 7) % 120,
            "order": i,
        })
    return products
